async function api(path,body,method=body===undefined?'GET':'POST'){const response=await fetch(path,{method,headers:{...(body!==undefined?{'Content-Type':'application/json'}:{}),...(session?{Authorization:`Bearer ${session.access_token}`}:{})},...(body!==undefined?{body:JSON.stringify(body)}:{}),cache:'no-store'});const result=await response.json();if(!response.ok){const error=new Error((result.error?.message??`请求失败（${response.status}）`)+(result.error?.diagnostic_number?`\n报错编号：${result.error.diagnostic_number}（在账号区“我的报错”中查询）`:''));error.status=response.status;throw error;}return result;}
