if(d.incomingClasses!==undefined){const e=groups(d.mode)[Number(d.ai)].effects[Number(d.ei)];if(el.value)e.source_unit_classes=el.value.split(',');else delete e.source_unit_classes;d.mode==='keyword'?changeKeyword():change();redrawPreview();return;}if(d.effect){const list=groups(d.mode)[Number(d.ai)].effects,e=list[Number(d.ei)];if(d.effect==='op'){const schema=effectSchemas(d.mode).find(s=>s.properties.op.const===el.value);list[Number(d.ei)]=makeEffect(el.value,d.mode);if(groups(d.mode)[Number(d.ai)].trigger==='while_active'&&el.value!=='unit_limit'){list[Number(d.ei)].target=editingSpec(d.mode).kind==='unit'?'self':'all_friendly_units';list[Number(d.ei)].duration='battle';}if(['summon','create_card','transform','liberate'].includes(el.value))list[Number(d.ei)].token_id=card.tokens.find(t=>!['summon','transform','liberate'].includes(el.value)||(t.kind??'unit')==='unit')?.token_id??'';}else{const value=effectFieldValue(effectSchemas(d.mode).find(s=>s.properties.op.const===e.op),d.effect,el.value,d.mode);if(value===undefined)delete e[d.effect];else e[d.effect]=value;}if(['on_kill_summon','deck_position','overflow'].includes(d.effect)&&!el.value)delete e[d.effect];if(e.op==='return_to_hand'&&d.effect==='cost_delta'){if(!el.value||Number(el.value)===0){delete e.cost_delta;delete e.duration;}else e.duration??='end_of_turn';}if(e.op==='develop'&&d.effect==='source'){if(e.source!=='tokens')delete e.token_ids;else{delete e.filter;e.token_ids=card.tokens.map(t=>t.token_id);}}syncAbilityTarget(groups(d.mode)[Number(d.ai)]);d.mode==='keyword'?changeKeyword():change();if(['op','target','source'].includes(d.effect)||e.op==='return_to_hand'&&d.effect==='cost_delta')draw();else redrawPreview();return;}
