if(d.token){const i=Number(d.index),t=card.tokens[i];if(d.token==='kind'){const next=changeKind({...t,kind:t.kind??'unit',abilities:t.abilities??[]},el.value);delete next.appearance;next.operation_cost=el.value==='unit'?1:0;next.cost??=1;card.tokens[i]=next;}else t[d.token]=el.type==='number'?Number(el.value):el.value;if(d.token==='sin'&&!el.value)t.sin=null;change();if(['kind','counter_trigger'].includes(d.token))draw();else redrawPreview();return;}
