document.addEventListener('input',event=>{if(event.target.tagName!=='SELECT'&&event.target.type!=='checkbox')try{update(event);}catch(e){notify(e.message,true);}});
document.addEventListener('change',async event=>{try{if(event.target.dataset.mediaFile){await uploadSound(event.target.files[0],event.target.dataset.mediaFile,event.target.dataset.mediaMode);}else if(event.target.hasAttribute('data-media-background')){await uploadArt(event.target.files[0],true,event.target.dataset.mediaMode);}else if(event.target.id==='faction-background-file'){await uploadFactionIcon(event.target.files[0],true);}else if(event.target.id==='faction-icon-file'){await uploadFactionIcon(event.target.files[0]);}else if(event.target.matches('[data-token-art-file],#card-art-file')){await uploadArt(event.target.files[0],false,'card',event.target.dataset.tokenArtFile??'');}else if(event.target.id==='import-file'){const f=event.target.files[0];if(!f)return;if(f.size>32768)throw new Error('导入文件不能超过 32 KiB。');requireLogin();const raw=JSON.parse(await f.text());const r=await api('/v1/card-drafts',{request_id:uid(),definition:raw.definition??raw});loadCard(r.result.definition);draft=r.result;redrawPreview();}else if(event.target.tagName==='SELECT'||event.target.type==='checkbox')update(event);}catch(e){notify(e.message,true);}});
window.addEventListener('hashchange',()=>{route=['cards','edit','keywords','keyword','factions','emotes'].includes(location.hash.slice(1))?location.hash.slice(1):'cards';filter='';draw();});
async function start(){try{contracts=await (await fetch('./contracts.json')).json();await accountsUI.init();const hash=new URLSearchParams(location.hash.slice(1)),code=hash.get('login');if(code){const next=hash.get('route')??'edit',editId=hash.get('card');history.replaceState(null,'',location.pathname+'#'+next);try{session=await api('/v1/browser-sessions/exchange',{code});localStorage.setItem('frontline.session',JSON.stringify(session));}catch(e){notify(e.message,true);}restore();newCard();account();await refresh(false);if(editId)openCardEditor(editId);}else{restore();account();if(session){try{session={...session,...await api('/v1/me')};localStorage.setItem('frontline.session',JSON.stringify(session));account();}catch{session=null;localStorage.removeItem('frontline.session');restore();account();notify('登录已过期，请重新登录。',true);}}await refresh(false);}route=['cards','edit','keywords','keyword','factions','emotes'].includes(location.hash.slice(1))?location.hash.slice(1):'cards';draw();setInterval(()=>refresh(['cards','keywords'].includes(route)).catch(()=>{$('#connection').textContent='连接中断，草稿已保存在本机';}),30000);}catch(e){$('#view').innerHTML='<section class="empty-state"><h3>暂时无法加载工坊</h3><p>请检查连接后刷新页面。本机草稿仍会保留。</p></section>';notify(e.message,true);}}
