function artImage(art){return art?.id&&/^[0-9a-f]{64}$/.test(art.id)?`<img class="card-art" src="/v1/card-art/${art.id}.png" alt="卡面" loading="lazy">`:'';}
function tokenArtIds(){return Object.fromEntries(card.tokens.filter(t=>tokenArts[t.token_id]?.id).map(t=>[t.token_id,tokenArts[t.token_id].id]));}
function tokenPreviewRecord(id){const t=card.tokens.find(t=>t.token_id===id);if(!t)return previewRecord();const known=cards.find(r=>r.derived_from?.card_id===editing?.card_id&&r.derived_from?.token_id===id&&r.revision===editing?.revision);return {definition:{...freshCard(),...clone(t),kind:t.kind??'unit',cost:t.cost??1,operation_cost:t.operation_cost??((t.kind??'unit')==='unit'?1:0),rarity:t.rarity??(card.veteran?.token_id===id?card.rarity:'standard'),sin:Object.hasOwn(t,'sin')?t.sin:card.veteran?.token_id===id?card.sin:null,faction_id:card.faction_id,appearance:{emblem:(t.kind??'unit')==='unit'?t.unit_class:t.kind}},art:tokenArts[id]??null,rules_text:(JSON.stringify(t)===JSON.stringify(cards.find(r=>r.card_id===editing?.card_id)?.definition.tokens.find(x=>x.token_id===id))?known?.rules_text:null)??((t.abilities?.length||t.keywords?.length)?'效果待校验':'无额外能力')};}
function artEditor(tokenId=''){const art=tokenId?tokenArts[tokenId]:cardArt,attr=tokenId?`data-art-token="${esc(tokenId)}"`:'';return `${tokenId?`<div class="token-art-preview" data-token-art-preview="${esc(tokenId)}">${cardFace(tokenPreviewRecord(tokenId),factions)}</div>`:artImage(art)}<div class="actions"><label class="secondary-button">${artBusy?'上传中…':art?'更换卡面':'上传卡面'}<input ${tokenId?`data-token-art-file="${esc(tokenId)}"`:'id="card-art-file"'} type="file" accept="image/png,image/jpeg,image/webp" ${artBusy?'disabled':''} hidden></label>${art?button('框选卡面','recrop-art',`${attr} ${artBusy?'disabled':''}`)+button('移除卡面','remove-art',`${attr} ${artBusy?'disabled':''}`,'ghost-button small'):''}</div><p class="hint">PNG / JPG / WebP，最多 8 MB</p>`;}

async function uploadArt(file,background=false,mode='card',tokenId=''){
  const spec=editingSpec(mode);
  if(!file||artBusy)return;requireLogin();
  if(!['image/png','image/jpeg','image/webp'].includes(file.type)||file.size>8*1024*1024)throw new Error('请选择 8 MB 以内的 PNG、JPG 或 WebP 图片。');
  const current=epoch;artBusy=true;draw();
  try{
    const bitmap=await createImageBitmap(file);
    try{
      if(bitmap.width*bitmap.height>32000000)throw new Error('图片尺寸过大，请缩小至 3200 万像素以内。');
      let max=1024,base64='';
      if(!background){const selected=await cropCard(bitmap,tokenId?tokenPreviewRecord(tokenId):previewRecord(),factions);if(!selected||current!==epoch)return;base64=selected.split(',')[1];}
      else do{const scale=Math.min(1,max/Math.max(bitmap.width,bitmap.height)),canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(bitmap.width*scale));canvas.height=Math.max(1,Math.round(bitmap.height*scale));canvas.getContext('2d').drawImage(bitmap,0,0,canvas.width,canvas.height);base64=canvas.toDataURL('image/png').split(',')[1];max=Math.floor(max*0.8);}while(base64.length>Math.ceil(2*1024*1024/3)*4&&max>=256);
      if(current!==epoch)return;
      const result=await api('/v1/card-art',{png_base64:base64});
      if(current!==epoch)return;
      if(background){spec.media??={};spec.media.background=result.art.id;}else if(tokenId){if(!card.tokens.some(t=>t.token_id===tokenId))return;tokenArts[tokenId]=result.art;}else cardArt=result.art;change();notify('卡面已上传，保存卡牌后生效。');
    }finally{bitmap.close();}
  }finally{artBusy=false;draw();}
}

function requireFaction(){if(!card.faction_id)return;const f=factions.find(f=>f.faction_id===card.faction_id);if(!f)throw new Error('请先创建阵营，再为卡牌选择阵营。');}
function factionBadge(id){const f=factions.find(f=>f.faction_id===id);return f?`<div class="faction-badge"><span data-faction-background="${esc(f.color)}">${f.icon_id?`<img src="/v1/card-art/${esc(f.icon_id)}.png" alt="">`:esc(f.name.slice(0,1))}</span>${esc(f.name)}</div>`:'<div class="author-mark">未指定阵营</div>';}
function renderFactions(){return `<div class="work-layout"><section class="form-panel"><div class="section-heading"><h3>${faction.faction_id?'修改阵营':'创建阵营'}</h3>${button('新建','new-faction','','ghost-button small')}</div><div class="field-grid">${field('阵营名称',input(faction.name,'data-faction="name" maxlength="64"'),true)}${field('颜色',input(faction.color,'data-faction="color"','color'))}${field('阵营类别',select('阵营类别',[['large','大阵营'],['normal','普通阵营'],['small','小阵营']],faction.category??'normal','data-faction="category"'))}</div><div class="faction-icon-editor"><span id="faction-swatch" class="faction-swatch" data-faction-background="${esc(faction.color)}">${faction.icon_id?`<img src="/v1/card-art/${esc(faction.icon_id)}.png" alt="阵营图标">`:esc(faction.name.slice(0,1)||'旗')}</span><label class="secondary-button">${factionBusy?'上传中…':'上传图标'}<input id="faction-icon-file" type="file" accept="image/png,image/jpeg,image/webp" ${factionBusy?'disabled':''} hidden></label>${faction.icon_id?button('移除图标','remove-faction-icon','','ghost-button small'):''}</div><div class="faction-background-editor">${faction.background_id?`<img src="/v1/card-art/${esc(faction.background_id)}.png" alt="阵营卡面背景" class="faction-background-image">`:''}<label class="secondary-button">上传卡面背景<input id="faction-background-file" type="file" accept="image/png,image/jpeg,image/webp" ${factionBusy?'disabled':''} hidden></label>${faction.background_id?button('移除背景','remove-faction-background','','ghost-button small'):''}</div><p class="hint">大阵营只能计入主罪孽，小阵营只能计入副罪孽，普通阵营两边均可；无罪孽牌暂不受类别限制，可补足名额。未单独上传卡面的牌使用阵营背景。</p>${button(faction.faction_id?'保存修改':'创建阵营','save-faction',factionBusy?'disabled':'','primary-button')}</section><section class="form-panel"><div class="section-heading"><h3>已登记阵营</h3>${lifecycle.filter("factions")}</div><div class="faction-list">${factions.some(f=>lifecycle.visible("factions",f))?factions.filter(f=>lifecycle.visible("factions",f)).map(f=>`<article class="faction-item">${factionBadge(f.faction_id)}<span class="tag">${({large:'大阵营',normal:'普通阵营',small:'小阵营'})[f.category??'normal']}</span>${f.archived?'<span class="tag">已归档</span>':''}${lifecycle.manage("factions",f.faction_id,f.can_edit)}${f.can_edit?button('修改','edit-faction',`data-id="${esc(f.faction_id)}"`,'ghost-button small'):''}</article>`).join(''):'<p class="muted">暂无阵营</p>'}</div></section></div>`;}
async function saveFaction(){requireLogin();if(factionBusy)return;const current=factionEpoch;const body={request_id:uid(),category:faction.category??'normal',name:faction.name.trim(),color:faction.color,icon_id:faction.icon_id,background_id:faction.background_id??null,...(faction.faction_id?{base_revision:faction.revision}:{role:faction.role})};const result=await api('/v1/factions'+(faction.faction_id?'/'+faction.faction_id:''),body,faction.faction_id?'PATCH':'POST');if(current===factionEpoch){faction=result;save();}await refresh();notify('阵营已保存');}
async function uploadFactionIcon(file,background=false){if(!file||factionBusy)return;requireLogin();if(!['image/png','image/jpeg','image/webp'].includes(file.type)||file.size>8*1024*1024)throw new Error('请选择 8 MB 以内的 PNG、JPG 或 WebP 图片。');const current=factionEpoch;factionBusy=true;draw();try{const bitmap=await createImageBitmap(file);try{if(bitmap.width*bitmap.height>32000000)throw new Error('图片尺寸过大，请缩小至 3200 万像素以内。');let png;if(background){const canvas=document.createElement('canvas');canvas.width=768;canvas.height=512;const ratio=Math.min(canvas.width/bitmap.width,canvas.height/bitmap.height),w=bitmap.width*ratio,h=bitmap.height*ratio;canvas.getContext('2d').drawImage(bitmap,(canvas.width-w)/2,(canvas.height-h)/2,w,h);png=canvas.toDataURL('image/png');}else png=await cropSquare(bitmap);if(!png||current!==factionEpoch)return;const r=await api('/v1/card-art',{png_base64:png.split(',')[1]});if(current===factionEpoch){faction[background?'background_id':'icon_id']=r.art.id;factionEpoch++;save();notify((background?'背景':'图标')+'已上传，保存阵营后生效。');}}finally{bitmap.close();}}finally{factionBusy=false;draw();}}

function paintTitlePreview(){const proof=$('.title-proof');if(!proof)return;const d=draft?.definition??card,color=sinInfo(d.sin).color;proof.style.backgroundColor=color;const name=proof.querySelector('.preview-name'),layout=titleLayout(d,titleMeasure);name.style.fontFamily=textFont(d.name);name.style.fontSize=layout.size+'px';name.style.whiteSpace='pre';name.textContent=layout.lines.join('\n');const emblem=proof.querySelector('.faction-badge>span');if(emblem)emblem.style.backgroundColor=color;}

document.addEventListener('change',event=>{const kind=event.target.dataset.contentFilter;if(kind){lifecycle.setFilter(kind,event.target.value);draw();}});

async function uploadSound(file,slot,mode='card'){
 const card=editingSpec(mode);
 if(!file||artBusy)return;requireLogin();const current=epoch;artBusy=true;draw();
 try{const wav_base64=await encodeAudio(file,slot==='music');const r=await api('/v1/card-sounds',{kind:slot==='music'?'music':'sound',wav_base64});if(current!==epoch)return;card.media??={};if(slot==='music')card.media.music=r.asset.id;else{card.media.sounds??={};card.media.sounds[slot]=r.asset.id;}change();notify('音频已上传，保存后生效。');}finally{artBusy=false;draw();}
}

function auraEffect(){return {op:'modify_stats',target:'all_friendly_units',attack_delta:1,health_delta:0,duration:'battle'};}

function legalEffectTargets(values,a,spec){return values.filter(t=>
 (t!=='attack_target'||['on_attack','after_attack','after_action'].includes(a.trigger)||a.trigger==='on_reveal'&&spec.counter_trigger==='enemy_unit_attacked')&&
 (t!=='adjacent_to_self'||(spec.kind??'unit')==='unit')&&
 (t!=='self'||(spec.kind??'unit')==='unit'&&!['on_death','on_reveal'].includes(a.trigger))&&
 (t!=='trigger_unit'||['own_unit_deployed','next_own_unit_deployed','enemy_unit_deployed','on_attacked','on_damaged','on_stack_gained','after_attack','after_move','after_action','own_unit_died','enemy_unit_died','on_attack','on_veteran','own_unit_attacked','enemy_unit_attacked','own_unit_retreated','enemy_unit_retreated','own_unit_returned','enemy_unit_returned','own_unit_entered','enemy_unit_entered','own_unit_attacked_hq','enemy_unit_attacked_hq','own_unit_became_veteran','enemy_unit_became_veteran'].includes(a.trigger)||(a.trigger==='on_reveal'&&spec.counter_trigger!=='enemy_order_played')));
}
function eventAbilityUI(a,ai,mode){
 const attrs=`data-ai="${ai}" data-mode="${mode}"`;
 if(a.trigger==='on_activate')return '<p class="hint">己方回合手动发动，每回合一次，不消耗行动次数或指挥点。</p>';
 if(!['after_attacked','own_unit_moved','enemy_unit_moved','own_card_played','enemy_card_played','on_keyword_lost','on_attacked','on_damaged','own_unit_deployed','enemy_unit_deployed','own_order_played','enemy_order_played','on_stack_gained','after_attack','after_move','after_action','own_unit_died','enemy_unit_died','on_attack','on_veteran','own_unit_attacked','enemy_unit_attacked','own_unit_retreated','enemy_unit_retreated','own_unit_returned','enemy_unit_returned','own_unit_entered','enemy_unit_entered','own_unit_attacked_hq','enemy_unit_attacked_hq','own_unit_became_veteran','enemy_unit_became_veteran'].includes(a.trigger))return '';
 return '<div class="field-grid">'+(['own_unit_retreated','own_unit_returned','own_unit_attacked','own_unit_entered','own_unit_deployed','own_unit_died'].includes(a.trigger)?field('事件来源',select('事件来源',[['','全部友方'],['self','仅自身'],['other','仅其他单位']],a.event_scope??'',`${attrs} data-event-scope`)):'')+(a.trigger==='on_stack_gained'?field('层数名称',input(a.stack??'',`${attrs} data-ability-stack="true" maxlength="32" placeholder="例如 high"`))+(!a.premise||a.premise.test==='compare'&&a.premise.left?.stack_count?.target==='self'&&a.premise.cmp==='gte'?field('至少层数（留空不限制）',input(a.premise?.right??'',`${attrs} data-stack-threshold="true" min="1" max="99"`,'number')):''):'')+field('最多触发（留空不限）',input(a.limit??'',`${attrs} data-ability-number="limit" min="1" max="999"`,'number'))+(a.limit?field('次数范围',select('次数范围',[['battle','本次在场'],['turn','每回合']],a.limit_scope??'battle',`${attrs} data-limit-scope`)):'')+(a.trigger==='on_damaged'?field('每累计损伤（留空每次受伤）',input(a.damage_step??'',`${attrs} data-ability-number="damage_step" min="1" max="10"`,'number')):'')+'</div>';
}

function hqTargetUI(s,attrs){return field('可选总部',select('可选总部',[['false','否'],['true','是']],String(s?.include_hq??false),attrs));}
function setSelector(s,key,value){if(key==="faction_id"){if(value){s.faction_id=value;delete s.include_hq;}else delete s.faction_id;return;}if(key==='unit_classes'){if(!value)delete s.unit_classes;else if(value!=='custom')s.unit_classes=unitGroups[value]??[value];delete s.include_hq;return;}if(key==='include_hq'){if(value==='true'){s.include_hq=true;s.row='any';delete s.unit_classes;delete s.faction_id;}else delete s.include_hq;}else{s[key]=value;if(key==='row'&&value!=='any')delete s.include_hq;}}

function catalogRows(list){return list.length?list.map(r=>`<article class="catalog-entry">${cardFace(r,factions)}<div class="catalog-entry-actions">${button('详情','detail',`data-id="${esc(r.card_id)}" data-kind="card"`,'ghost-button small')}${!r.derived_from||(!r.derived_from.retired&&(r.can_edit??r.owned_by_me))?button((r.can_edit??r.owned_by_me)?'修改':'复制','edit-card',`data-id="${esc(r.card_id)}"`,'secondary-button small'):''}${r.derived_from?`<span class="tag">衍生 · ${r.definition.deck_building==='allowed'?'可入组':'不可入组'}</span>`:''}${r.archived?'<span class="tag">已归档</span>':''}${r.can_edit?button('卡包','series-card',`data-id="${esc(r.card_id)}"`,'ghost-button small'):''}</div></article>`).join(''):'<section class="empty-state full-width"><h3>没有匹配的卡牌</h3></section>';}
function catalogSelection(){return filterCards(cards.filter(r=>lifecycle.visible('cards',r)),cardFilters,{factions,keywords,series:seriesCatalog});}
function renderCardCatalog(){const list=catalogSelection();return filtersUI(cardFilters,cards,factions,keywords,lifecycle.filter('cards'),seriesCatalog,seriesUI.toolbar(cardFilters.series)).replace('<span id="catalog-count" role="status"></span>',`<span id="catalog-count" role="status">${list.length} / ${cards.length} 张</span>`).replace('<span id="catalog-filter-error" role="alert"></span>',`<span id="catalog-filter-error" role="alert">${esc(filterError(cardFilters))}</span>`)+`<div id="catalog-grid" class="archive-grid">${catalogRows(list)}</div>`;}
function updateCatalogResults(){const seriesActions=$('#catalog-series-actions');if(seriesActions)seriesActions.innerHTML=seriesUI.toolbar(cardFilters.series);const grid=$('#catalog-grid');if(!grid)return;const list=catalogSelection();grid.innerHTML=catalogRows(list);paintCardFaces(grid);$('#catalog-count').textContent=`${list.length} / ${cards.length} 张`;$('#catalog-filter-error').textContent=filterError(cardFilters);}
function unitClassUI(s,attrs){const list=s?.unit_classes??[];const value=Object.entries(unitGroups).find(([,v])=>v.length===list.length&&v.every(c=>list.includes(c)))?.[0]??(list.length===1?list[0]:list.length?'custom':'');return field('目标兵种',select('目标兵种',[['','全部单位'],...['infantry','tank','artillery','fighter','bomber','air','ground'].map(k=>[k,label(k)]),...(value==='custom'?[['custom','自定义兵种组合']]:[])],value,attrs));}
function premiseUI(a,ai,mode){const p=a.premise,attrs=`data-ai="${ai}" data-mode="${mode}"`,simple=p?.test==='compare'&&p.left?.count_units&&typeof p.right==='number';return `<details class="premise-editor" ${p?'open':''}><summary>前提条件${p?' · 已设置':''}</summary><div class="field-grid">${field('条件',select('条件',[['none','无条件'],['presence','在场兵种数量'],['own_turn','仅己方回合'],['enemy_turn','仅对方回合'],...(p&&!simple?[['custom','组合条件（保留现有）']]:[])],p?(p.test==='turn_owner'?(p.side==='owner'?'own_turn':'enemy_turn'):simple?'presence':'custom'):'none',`${attrs} data-premise="kind"`))}${simple?field('哪一方',select('哪一方',['ally','enemy','any'],p.left.count_units.side,`${attrs} data-premise="side"`))+field('兵种',select('条件兵种',[['','全部单位'],...['infantry','tank','artillery','fighter','bomber','air','ground'].map(k=>[k,label(k)])],Object.entries(unitGroups).find(([,v])=>JSON.stringify(v)===JSON.stringify(p.left.count_units.unit_classes))?.[0]??p.left.count_units.unit_classes?.[0]??'',`${attrs} data-premise="classes"`))+field('战线',select('条件战线',['any','front','support'],p.left.count_units.row??'any',`${attrs} data-premise="row"`))+field('比较',select('比较',[['gte','至少'],['gt','多于'],['eq','等于'],['lte','至多'],['lt','少于'],['ne','不等于']],p.cmp,`${attrs} data-premise="cmp"`))+field('数量',input(p.right,`${attrs} data-premise="amount" min="0" max="100"`,'number')):''}</div>${p?`<p class="premise-summary">${esc(premiseSummary(p))}</p>`:''}</details>`;}

function openCardEditor(id){
 const entry=cards.find(c=>c.card_id===id);if(!entry)return;
 const r=entry.derived_from?cards.find(c=>c.card_id===entry.derived_from.card_id):entry;
 if(!r)throw new Error('来源卡已移除，请刷新卡库。');
 if(entry.derived_from&&!r.definition.tokens.some(t=>t.token_id===entry.derived_from.token_id))throw new Error('此衍生卡已在来源卡的新版本中移除，仅保留历史版本。');
 if(entry.derived_from&&!(r.can_edit??r.owned_by_me))throw new Error('只能由作者或管理员修改衍生卡。');
 editingToken=entry.derived_from?.token_id??null;editorId++;pendingSave=null;card=clone(r.definition);titleDraft=null;cardArt=r.art??null;tokenArts=clone(r.token_art??{});
 editing=(r.can_edit??r.owned_by_me)?{card_id:r.card_id,revision:r.revision,series:r.series??1}:null;selectedSeries=editing?(r.series??1):null;
 if(!editing)card.name=(card.name+' 副本').slice(0,64);
 source='';savedFingerprint=editing?fingerprint():'';change();
}
function renderDerivedEditor(){
 const token=card.tokens.find(t=>t.token_id===editingToken);
 return `<section class="form-panel"><div class="section-heading"><div><h3>${esc(token.name)}</h3><p class="version-note">衍生自 ${esc(card.name)}</p></div>${button('返回来源卡','edit-source','','ghost-button small')}</div><p class="hint">保存后，来源卡与衍生卡同步更新；旧版本仍保留。</p>${tokensUI(editingToken)}<div class="actions button-row">${button(saveBusy?'保存中…':'保存','save-card',saveBusy||artBusy?'disabled':'','primary-button')}</div></section>`;
}

function cardFilterUI(e,attrs){if(e.op==='develop'&&e.source==='tokens')return '<span class="hint">按上方选择的候选卡池开发</span>';const f=e.filter??{};return `${e.op==='modify_hand_cost'?field('阵营',select('手牌阵营',[['','不限'],...factions.map(f=>[f.faction_id,f.name])],f.faction_id??'',`${attrs} data-card-filter="faction_id"`)):''}${e.op==='modify_cards'?`<label class="inline-option"><input type="checkbox" ${attrs} data-card-filter="same_as_discarded" ${f.same_as_discarded?'checked':''}>与本组弃置卡同名</label>`:''}${field('名称包含',input(f.name_contains??'',`${attrs} data-card-filter="name_contains" maxlength="64" placeholder="例如：集团军"`))}${field('准确名称',input(f.card_name??'',`${attrs} data-card-filter="card_name" maxlength="64"`))}${e.op==='modify_cards'?'':field('卡牌类型',select('筛选类型',[['','不限'],['unit','单位'],['order','指令'],['counter','反制'],['field','场地']],f.kind??'',`${attrs} data-card-filter="kind"`))}${field('兵种',select('筛选兵种',[['','不限'],...['infantry','tank','artillery','fighter','bomber'].map(x=>[x,label(x)])],f.unit_class??'',`${attrs} data-card-filter="unit_class"`))}`;}


async function resumeReport(number){
 requireLogin();if(busy||keywordBusy||saveBusy||previewBusy)throw new Error('请先完成当前操作。');
 const r=await api('/v1/diagnostics/resume?number='+encodeURIComponent(number));
 localStorage.setItem(key()+'.before-report-resume',JSON.stringify({card,keyword,source,keywordSource,editing,cardArt,saved_at:new Date().toISOString()}));
 if(r.target_kind==='keyword'){
  changeKeyword();metadataOnly=false;keyword=freshKeyword();keyword.name=r.suggested_name;keywordSource=r.source_text;
  save();setRoute('keyword');keywordBusy=true;draw();const current=keywordEpoch;
  try{interpretation=await api('/v1/mechanism-reviews',{request_id:uid(),kind:'keyword',report_number:number});await pollInterpretation(interpretation.generation_id,current);}finally{if(keywordEpoch===current){keywordBusy=false;draw();}}
  return;
 }
 change();editing=null;editingToken=null;editorId++;titleDraft=null;cardArt=null;tokenArts={};
 card=readyCard({...freshCard(),...r.card_blueprint},keywords);effectMode=r.card_blueprint.effect_mode??"append";delete card.effect_mode;
 source=r.source_text;mechanismHistory=[{role:'user',text:source},...r.history.flatMap(h=>[{role:'assistant',text:h.formal_text??''},{role:'user',text:[h.feedback,...(h.answers??[]).map(a=>a.question+'：'+a.answer)].filter(Boolean).join('\n')}])];
 save();route='edit';location.hash='#edit';draw();busy=true;redrawPreview();const current=epoch;
 try{generation=await api('/v1/mechanism-reviews',{request_id:uid(),kind:r.target_kind,report_number:number,editor_revision:revision});await pollGeneration(generation.generation_id,current);}finally{if(epoch===current){busy=false;redrawPreview();}}
}

function factionTargetUI(s,attrs){return field("限定阵营",select("限定阵营",[["","不限阵营"],...factions.map(f=>[f.faction_id,f.name])],s?.faction_id??"",attrs));}
